budget.value:
fun p =>
  have K := ⌈p.L * p.Δ / p.ε⌉₊;
  have B := ⌈p.σ ^ 2 / p.ε⌉₊;
  have r := fun i => ∑ j, if p.h j ≤ p.h i then (p.h j)⁻¹ else 0;
  have C := p.b * ↑(p.d * (1 + (2 + p.d + K + B).log2) + DistributedTemplate.clockBits);
  262144 * ↑(1 + K) * (sInf (Set.range fun i => p.h i + ↑(1 + B) / r i) + p.l + C)

